tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets ln -s '$shared' shared.dat &&
echo 'sparcc( #if $label: label=${ str($label).replace(",","-") }, #end if #if $groups: groups=${ str($groups).replace(",","-") }, #end if samplings=$samplings, iterations=$iterations, permutations=$permutations, method=$method, shared=shared.dat )' | sed 's/ //g; s/,)$/)/' ## mothur trips over whitespace; a trailing comma segfaults mothur >1.42 | mothur | tee mothur.out.log
